solution.code:
#include <stdio.h>

int power(int base, int exp) {
    if (exp == 0) {
        return 1;
    }
    int half = power(base, exp / 2);
    return exp % 2 == 0 ? half * half : half * half * base;
}

int main() {
    printf("%d\n", power(3, 7));
    return 0;
}
